from pptx import Presentation
import os

prs = Presentation('input.pptx')

for i, slide in enumerate(prs.slides):
    print(f"Slide {i+1}")
    for shape in slide.shapes:
        if shape.has_text_frame:
            for paragraph in shape.text_frame.paragraphs:
                for run in paragraph.runs:
                    print(f"Text Box: {run.text}")
        if shape.has_table:
            print("Table found (standard PPT table, not embedded Excel)")
        if shape.shape_type == 12: # 12 is OLE_OBJECT
            print(f"Embedded Object found: {shape.name}")
            if hasattr(shape, 'ole_format'):
                print(f"  ProgID: {shape.ole_format.prog_id}")

