args.new_string:
from pptx import Presentation
from pptx.enum.shapes import MSO_SHAPE_TYPE
import os

prs = Presentation('input.pptx')

for i, slide in enumerate(prs.slides):
    print(f"Slide {i+1}")
    for shape in slide.shapes:
        print(f"Shape: {shape.name}, Type: {shape.shape_type}")
        if shape.has_text_frame:
            print(f"  Text: {shape.text_frame.text.strip()}")
        if shape.shape_type == MSO_SHAPE_TYPE.OLE_CONTROL_OBJECT or shape.shape_type == MSO_SHAPE_TYPE.LINKED_OLE_OBJECT or shape.shape_type == MSO_SHAPE_TYPE.EMBEDDED_OLE_OBJECT:
            print(f"  OLE Object: {shape.name}")
            # Try to get more info
            try:
                print(f"  ProgID: {shape.ole_format.prog_id}")
            except:
                pass
        if shape.shape_type == MSO_SHAPE_TYPE.PICTURE:
            print(f"  Picture")
        if shape.shape_type == MSO_SHAPE_TYPE.GRAPHIC_FRAME:
            print(f"  Graphic Frame")
            # Embedded objects are often inside Graphic Frames if they are OLE
            if hasattr(shape, 'ole_format'):
                print(f"    Has OLE Format, ProgID: {shape.ole_format.prog_id}")

