import openpyxl

wb = openpyxl.load_workbook('temp_pptx/ppt/embeddings/Microsoft_Excel_Worksheet.xlsx', data_only=False)
sheet = wb.active

for row in sheet.iter_rows(values_only=False):
    row_values = []
    for cell in row:
        if cell.value is not None:
            val = cell.value
            if cell.data_type == 'f':
                row_values.append(f"FORMULA:{val}")
            else:
                row_values.append(str(val))
        else:
            row_values.append("None")
    print("\t".join(row_values))

